/**
 * WHAT THE TOOLS SEND when they connect, list the catalog, describe a table and query it — RECORDED LIVE (with psql's,
 * ./psql.ts, recorded earlier with `psql -E`): each tool at the version below was
 * connected to Mason's Postgres listener over a small synthetic shop (the tables of ./shop.ts) with `MASON_PG_TRACE=1`,
 * which logs every statement text a session receives (src/api/postgres/server.ts), and walked through what its
 * `recorded` says; the statements are the trace's, in the order first seen, each once, the OID of a table written
 * `{{oid:<table>}}` (the test fills in the catalog's). tests/duck-corpus.test.ts sends every one to the listener and
 * holds it to an answer: a tool whose catalog statement is refused shows an empty database, and one whose query is
 * refused shows an error where the user expected numbers.
 *
 * The listener the tools were recorded against offered each table's METRICS too, which a copied table has not: the
 * statements that read one (`MEASURE(revenue)`, a sum of a metric) are left out here, and the select items that named
 * a metric as a column (Metabase's fingerprinting and its derived tables name every column the catalog listed) are
 * taken out of the statements they were in. What a tool sends is otherwise as recorded.
 *
 * DBeaver was driven by a person at the screen (its navigator has no headless mode) under the same trace. Tableau and
 * Power BI are not recorded.
 */

export interface ToolCorpus {
  tool: string;
  /** the release recorded */
  version: string;
  /** how it was driven while the trace ran */
  recorded: string;
  /** what the tool sent, in the order first seen */
  statements: string[];
}

